INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7f17923c-1004-4809-bd73-bfa072fec6ee', '21feff02-016d-46e2-bb9d-c27495133b1b', '10. óra: Gyakorlóóra. Hány eset van? Számoljuk össze!', 'Összeszámlálási feladatok gyakorlása fagráffal és táblázattal.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "a9b0987c-0124-4a77-9316-8fa82aa9cba3", "text": "Hány 2 jegyű páros szám képezhető az 1, 2, 3 számjegyekből (számjegyismétlés nélkül)?", "type": "multiple-choice", "options": [{"id": "d4038750-07c6-4854-ad59-1995ad656f7c", "text": "2 (12, 32)", "isCorrect": true}, {"id": "96410a5f-9080-498d-96d8-e770f644763b", "text": "3", "isCorrect": false}, {"id": "bc809a72-3975-45c1-a1bf-3383afb041e5", "text": "4", "isCorrect": false}, {"id": "802b7a22-31db-46d5-84ee-47350934cec2", "text": "6", "isCorrect": false}], "timeLimit": 15}, {"id": "26f2f663-af05-4af0-997f-095db803037d", "text": "Három barát köszöntésekor (mindenki mindenkivel kezet fog) hány kézfogás történik?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "c5ae2d92-49de-4f49-a6bc-3fbd7f65a429", "text": "A fagráf ágai az egyes döntési lépéseket ábrázolják.", "type": "true-false", "options": [{"id": "54dcb74e-014c-45c5-b1ce-186df9903974", "text": "Igaz", "isCorrect": true}, {"id": "e1a81614-90fc-45c5-96ac-b4300c80ce5f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4535c835-40e9-4b4c-8d9a-159448d8c8a0", "text": "Hány különböző sorrendben futhat be a célba 3 versenyző (A, B, C)? (3! = 3*2*1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "d5d17583-3ca0-4e6b-ba62-41d784d1eaaf", "text": "Ha 4 csapat játszik körmérkőzést (mindenki mindenkivel egyszer), hány mérkőzést játszanak összesen?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "b35d59f6-d888-467b-a89f-15561145613a", "text": "Egy szabályos dobókocka eldobásakor 6-féle kimenetel lehetséges.", "type": "true-false", "options": [{"id": "69fa3ae2-3cbf-4476-becd-73c01ca6f6b9", "text": "Igaz", "isCorrect": true}, {"id": "0e8e09a7-aaab-4cc1-a5f9-ba7499c80d2f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ceaf49a1-787d-4924-acd2-c581fd8e0e29", "text": "Hány kétjegyű szám képezhető a 0 és 5 számjegyekből (0 nem lehet az első számjegy)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f8c110ec-37b6-40f3-9e26-6e977cacfbfc', '21feff02-016d-46e2-bb9d-c27495133b1b', '11. óra: Összeszámlálási feladatok megoldása', 'Önálló feladatmegoldás rendszerezett felsorolással és faábrával.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "72299155-523b-48b0-be02-6a4b1b401905", "text": "Hányféleképpen rakhatunk sorba 4 különböző könyvet a polcon? (4*3*2*1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "0e758606-9a1e-4d5d-a62d-3514b252a938", "text": "Hány 3 jegyű szám képezhető a 7, 8, 9 számjegyekből ha mindegyiket csak egyszer használhatjuk fel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "ef269b03-725a-45e2-9529-5c7662ed105c", "text": "Az ágrajz utolsó szintjén lévő levelek száma megadja az összes lehetséges kimenetelt.", "type": "true-false", "options": [{"id": "9f525646-8d54-4d71-b96c-f2a014d97057", "text": "Igaz", "isCorrect": true}, {"id": "480f0e4f-f7b9-4ab2-8173-e143907a80e8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e5772619-e893-4aeb-afdd-da66ea238f6b", "text": "Melyik állítás igaz a valószínűségi kísérletekre?", "type": "multiple-choice", "options": [{"id": "5abcf925-eba5-4e4e-ac4e-fbfdff75ad3c", "text": "A lehetséges esetek száma a kedvező és kedvezőtlen esetek összege", "isCorrect": true}, {"id": "62a1bcdb-e521-4d19-893b-28c43c24e170", "text": "Mindig csak 1 eset lehetséges", "isCorrect": false}, {"id": "b1080015-8cec-4eed-b08f-2cdb8ea96c20", "text": "Sohasem lehet kiszámolni az esetek számát", "isCorrect": false}, {"id": "4b323100-9c68-4b25-8132-5607a38db9d2", "text": "Csak páros szám lehet az eredmény", "isCorrect": false}], "timeLimit": 15}, {"id": "412ad534-c3fd-4b58-867f-4c2ea0b536c7", "text": "Hányféle kétgombócos fagyit választhatunk 3-féle ízből, ha két különböző ízt kérünk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "e607a664-15e0-4950-81bc-50a9683ced2c", "text": "Ha egy feldobott pénzérmét kétszer dobunk fel egymás után, a lehetséges kimenetelek száma 4.", "type": "true-false", "options": [{"id": "2e01cd3d-7f10-4c42-a7d9-8d60eb61ae54", "text": "Igaz (FF, FI, IF, II)", "isCorrect": true}, {"id": "a14b610d-1f03-4fe7-8e7b-9d93aafc0e0e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "147f3ed4-811e-47e1-afee-c565c14c4bf9", "text": "Hány válaszlehetőség van egy 4 opciós feleletválasztós kérdésnél?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('90c136bc-2881-4c96-abed-a5b66ea055f0', '21feff02-016d-46e2-bb9d-c27495133b1b', '12. óra: Számonkérés', 'Az egész számok műveleteiből és az összeszámlálásból tanultak számonkérése (10 kérdés).', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "4edfc65d-2b32-4659-9d78-eac85089b8e8", "text": "1. Mennyi (-15) + (+20)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "1ee81ce6-5fa5-4ac9-8759-b6d0b636bc8d", "text": "2. Mennyi (-6) * (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "5efd4c9a-07d0-499e-9449-c4f0fabbc88a", "text": "3. Mennyi (-54) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-6"}, {"id": "0ced915b-4fc4-49df-99ca-8f7ebd37b5cf", "text": "4. Melyik szám abszolút értéke nagyobb: |-30| vagy |+20|?", "type": "multiple-choice", "options": [{"id": "d357457d-bcb0-40a4-a8d6-7721b2897d85", "text": "|-30|", "isCorrect": true}, {"id": "e8742dfb-cbcb-41c1-b3b4-ed3288773e2c", "text": "|+20|", "isCorrect": false}, {"id": "16d8c45c-78df-4b4b-8fae-36f33c931fe5", "text": "Egyenlőek", "isCorrect": false}, {"id": "4db60ee7-8fe9-49fb-8bcb-16a964a3d2e2", "text": "Egyik sem", "isCorrect": false}], "timeLimit": 15}, {"id": "bb68bb39-a4c4-4cff-9981-9474354461c1", "text": "5. Mennyi (-3) * (-2) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}, {"id": "8c6db3aa-607e-4832-89d8-ab8689dea210", "text": "6. A negatív szám szorzása negatív számmal pozitív eredményt ad.", "type": "true-false", "options": [{"id": "f2eb20f7-a5f3-4c06-b5eb-22a1262469c5", "text": "Igaz", "isCorrect": true}, {"id": "3836e7a3-0c66-42d0-a1ca-84ab83d85923", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2a431aac-00a7-4608-8415-731496fa4a10", "text": "7. Hány különböző sorrendben ülhet le 3 gyerek egy padra?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "e9f5a84e-0373-4a6e-918b-74a77276875e", "text": "8. Mennyi (-40) : (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "f63cf384-77e5-487b-a48c-79aaf093361e", "text": "9. A nullának nincs ellentettje (vagy önmaga az ellentettje).", "type": "true-false", "options": [{"id": "05b9237d-1548-4649-9588-20bc8876e437", "text": "Igaz", "isCorrect": true}, {"id": "1bb0d3d4-006d-4874-94a7-626d71df3c13", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d73a50d5-01c0-4a3e-a87b-31e610d67f30", "text": "10. Mennyi (-10) + (-20) - (-15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('520ffcfe-8872-4b81-b6c6-d9701615dfba', '21feff02-016d-46e2-bb9d-c27495133b1b', '13. óra: Osztó, többszörös', 'Osztó, többszörös fogalma, osztópárok meghatározása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "fdac5c27-0746-4f18-a809-53c55a02bce6", "text": "Mit nevezünk egy ''a'' természetes szám osztójának?", "type": "multiple-choice", "options": [{"id": "dd073718-f75b-46ac-921f-e492a000c388", "text": "Azt a ''b'' számot, amellyel ''a''-t elosztva a maradék 0", "isCorrect": true}, {"id": "1ae03347-ef68-4b49-8f1b-d2122e6fc07f", "text": "Azt a számot, amit ''a''-hoz hozzáadunk", "isCorrect": false}, {"id": "c1152ef0-85ef-46e5-b4dd-d04cf3eabe49", "text": "Azt a számot, ami nagyobb ''a''-nál", "isCorrect": false}, {"id": "c59f741d-b080-4ac3-a39f-ada596170cf2", "text": "Minden páratlan számot", "isCorrect": false}], "timeLimit": 15}, {"id": "23e13bf2-0859-4992-95a2-ce973a3daa85", "text": "Az 1 minden természetes számnak osztója.", "type": "true-false", "options": [{"id": "149727a6-0205-4cd0-8ef3-5380783dcbec", "text": "Igaz", "isCorrect": true}, {"id": "48cf32e7-e5c0-47f3-ac2a-cf46a4dacb53", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7ab162d9-1dfc-487b-a5a4-6a6c8c8689cf", "text": "Hány osztója van a 12-nek? (1, 2, 3, 4, 6, 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "0b3b135c-f4c7-48ea-a45f-0d9e01992f59", "text": "Melyik szám a 15 többszöröse az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "5cd551c2-0fb2-4bc3-8709-d778901c2bd1", "text": "45", "isCorrect": true}, {"id": "15764246-0ac1-4e31-b6bf-5b4b93df03c4", "text": "5", "isCorrect": false}, {"id": "9dc3fd38-cd87-4f6f-a14d-bfdbe292c619", "text": "3", "isCorrect": false}, {"id": "d2f88f49-e3d7-4693-a7f0-062c96f2ba52", "text": "10", "isCorrect": false}], "timeLimit": 15}, {"id": "e458b6e9-3771-4d96-ac58-4c9d7b6da691", "text": "Minden számnak végtelen sok többszöröse van.", "type": "true-false", "options": [{"id": "7e199d66-dd26-455c-8e25-5b6939f18b68", "text": "Igaz", "isCorrect": true}, {"id": "419eebc2-40f0-42ba-a371-6e5dd54b06e8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3195b86f-8ff3-487b-9ff7-db6b782e304e", "text": "Mi a 20 legkisebb pozitív osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "7e4f9174-502e-4fdd-9901-67c7e4284f04", "text": "Mi a 20 legnagyobb osztója önmagán kívül?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5a8ddf52-c5ad-4ed4-beef-343c81671c06', '21feff02-016d-46e2-bb9d-c27495133b1b', '14. óra: Számolás maradékokkal', 'Az osztási maradék fogalma, paritás vizsgálata, összeg maradéka.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "fd379178-3cdf-4c8c-b14c-2ced44a52239", "text": "Mennyi a maradék, ha 23-at elosztjuk 5-tel? (23 = 4*5 + 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "a654f753-8fe5-4366-8247-589d10aa1f8a", "text": "Egy számot 4-gyel elosztva a lehetséges maradékok: 0, 1, 2, 3.", "type": "true-false", "options": [{"id": "dfd056b8-eeb1-47be-93f6-25dc133cb3a4", "text": "Igaz", "isCorrect": true}, {"id": "76bdca74-c7e3-4f69-a78c-4014a4d7f4ef", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4b0fcd62-c5a9-428f-a412-e7042f5ee1cb", "text": "Milyen maradékot ad 2-vel osztva minden páratlan szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "946ccf71-b51a-4ace-8dab-db8ebaa1f0e9", "text": "Két páratlan szám összege mindig páros szám.", "type": "true-false", "options": [{"id": "67c11183-108a-457f-8d64-92e811f8b4e2", "text": "Igaz (páratlan + páratlan = páros)", "isCorrect": true}, {"id": "bb94e63b-225f-4537-8035-41832ab3dcff", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "16112457-bb72-449b-8015-a94762127d4b", "text": "Mennyi a maradék 37 : 10 esetén?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "68bb145c-6b90-44ad-a898-2ae51c580988", "text": "Két páros szám szorzata mindig páros szám.", "type": "true-false", "options": [{"id": "72157852-01bf-4856-a298-53df7c4b5559", "text": "Igaz", "isCorrect": true}, {"id": "b447f4cd-d29a-4bc5-b572-afad0fc6a7d1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "66c7bd1f-044e-4499-b317-cff33afcf68a", "text": "Melyik szám ad 0 maradékot 3-mal osztva?", "type": "multiple-choice", "options": [{"id": "5a29382f-e57b-4d3c-b40e-aeee2db0050c", "text": "15", "isCorrect": true}, {"id": "12401e22-1508-4a1f-b479-75828b5be1fa", "text": "16", "isCorrect": false}, {"id": "88e114b8-1e18-4a92-8715-54ac36370359", "text": "17", "isCorrect": false}, {"id": "7cbee4eb-e958-446e-97f0-774a7d47dbb1", "text": "19", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('de54f115-e397-471f-b4a5-ea07b38abcab', '21feff02-016d-46e2-bb9d-c27495133b1b', '15. óra: Hány osztója van?', 'Természetes számok csoportosítása osztóik száma alapján, prímek és összetett számok.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "a74f5b4e-ced4-4afb-9385-079385351396", "text": "Hogyan nevezzük azokat a számokat, amelyeknek pontosan 2 osztójuk van (1 és önmaga)?", "type": "multiple-choice", "options": [{"id": "f20b73a2-eef6-4a7f-aa73-f86277e0f4e3", "text": "Prímszámok (prímek)", "isCorrect": true}, {"id": "41830cf5-aaba-4f6e-b14e-c4006360ce97", "text": "Összetett számok", "isCorrect": false}, {"id": "fd29325e-a88c-4cba-878a-b8b518100441", "text": "Páros számok", "isCorrect": false}, {"id": "491085c5-0fd2-4b8c-a341-4a3380aa6e2f", "text": "Negatív számok", "isCorrect": false}], "timeLimit": 15}, {"id": "df520491-d9fd-4633-bfc4-6878a0499474", "text": "Az 1 prímszám.", "type": "true-false", "options": [{"id": "2ae78a63-f474-4a33-a322-7ee00d985914", "text": "Igaz", "isCorrect": false}, {"id": "2ca05c57-20e3-4ae7-8882-94bb7d23f34e", "text": "Hamis (az 1 sem nem prím, sem nem összetett)", "isCorrect": true}], "timeLimit": 15}, {"id": "da2510cf-2574-4c6f-911e-76dc228fc6de", "text": "Melyik a legkisebb prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "7d1c1705-60c2-49b2-8e14-d228133606b9", "text": "Melyik az egyetlen páros prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "5bcda904-d1ce-47e8-8d65-bc87f4966fa9", "text": "Azokat a számokat, amelyeknek 2-nél több osztójuk van, összetett számoknak nevezzük.", "type": "true-false", "options": [{"id": "477b6656-4e20-4ddc-b1b6-f2e81f33bfb5", "text": "Igaz", "isCorrect": true}, {"id": "45e21e42-2c6b-46cd-8827-9ea86a4d2b77", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c7b7ca45-ea23-4a52-b710-f977d6bf6472", "text": "Hány osztója van a 7-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "4396f9bf-cab7-451c-96c4-23cdc562ab0b", "text": "Melyik prím az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "3f42220c-00ef-4ff2-a118-a384909ffe00", "text": "13", "isCorrect": true}, {"id": "6eb1350b-26dc-46e6-a675-010245a9a460", "text": "9", "isCorrect": false}, {"id": "81171348-8131-4031-852b-00ae08bf3106", "text": "15", "isCorrect": false}, {"id": "c9ccd8dc-2a8a-4073-9452-b11b9e984b8b", "text": "21", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e0bd7cf3-b8a7-4b69-b487-a3ec1c9548d7', '21feff02-016d-46e2-bb9d-c27495133b1b', '16. óra: Feladatok az osztók számának meghatározására, számolás maradékokkal', 'Szöveges feladatok az osztókról és maradékokról.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "5ed1fb3d-f14d-438d-a099-153093c33963", "text": "Hány osztója van a 9-nek? (1, 3, 9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "4eb49da5-4695-4f48-aa5e-99e0b2c4b062", "text": "A négyzetszámoknak páratlan számú osztójuk van.", "type": "true-false", "options": [{"id": "509b666c-89a4-4a3a-ae30-5d3582c766d8", "text": "Igaz (pl. 9-nek 3 osztója van: 1, 3, 9)", "isCorrect": true}, {"id": "14833aa7-5469-4b6a-8a26-2d7d6c299dfb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "73782450-c45f-4658-82fa-0f4ef3b33930", "text": "Ha 25 alma van és 4 gyerek között egyenlően elosztjuk, hány alma marad a kosárban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "db977deb-f360-4fec-8e1f-bb87a029d2be", "text": "Hány prímszám van 10 és 20 között? (11, 13, 17, 19)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "3057dc5e-f57a-4624-9abd-dd641b6e7c03", "text": "Melyik szám összetett szám az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "53d8aeaf-ee74-4f35-b825-242e704ea3ee", "text": "27 (osztói: 1,3,9,27)", "isCorrect": true}, {"id": "08fd5dc5-31a9-4863-8ff5-5c163cefa1e0", "text": "23", "isCorrect": false}, {"id": "97c9456d-9ac9-42d3-96dc-bda10b11659f", "text": "29", "isCorrect": false}, {"id": "71ba21a1-b4d4-4a02-9dbf-ba3ac7e592ab", "text": "31", "isCorrect": false}], "timeLimit": 15}, {"id": "3e61e9fc-2d35-464d-bd50-8e9afc753e4c", "text": "Minden páratlan szám prímszám.", "type": "true-false", "options": [{"id": "5dfc0c12-6254-4fa6-90ab-0c3148737071", "text": "Igaz", "isCorrect": false}, {"id": "3abcbad8-6945-48f5-badd-c2d230c40da3", "text": "Hamis (pl. 9, 15, 21 nem prím)", "isCorrect": true}], "timeLimit": 15}, {"id": "b3a1c999-5b8f-4851-88a2-679d0f031f54", "text": "Mennyi a legkisebb kétjegyű prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a1089a21-65b5-4c6f-88c4-cd96ab4e5383', '21feff02-016d-46e2-bb9d-c27495133b1b', '17. óra: Oszthatóság 2-vel, 5-tel, 10-zel', 'Oszthatósági szabályok az utolsó számjegy alapján.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "aa85197e-0c2a-446f-ab65-406a3e08b3a5", "text": "Mikor osztható egy szám 2-vel?", "type": "multiple-choice", "options": [{"id": "42e6d560-4d1b-448a-9cab-e5017d6cdac0", "text": "Ha az utolsó számjegye páros (0, 2, 4, 6, 8)", "isCorrect": true}, {"id": "499098b5-f1bd-4220-bf68-f601cf7044e3", "text": "Ha a számjegyek összege 2", "isCorrect": false}, {"id": "6634f209-342f-4dec-9d29-e118ab5878f6", "text": "Ha 5-re végződik", "isCorrect": false}, {"id": "73dd9751-0120-44d6-9a13-1d21f38eef02", "text": "Minden szám osztható 2-vel", "isCorrect": false}], "timeLimit": 15}, {"id": "cf048ca2-b5c8-4740-834a-c15ca163004f", "text": "Mikor osztható egy szám 5-tel?", "type": "multiple-choice", "options": [{"id": "04d174e6-c980-423a-ac1c-5a178d72da06", "text": "Ha az utolsó számjegye 0 vagy 5", "isCorrect": true}, {"id": "b2d74a4f-0530-460c-b786-da015dfcf372", "text": "Ha 2-re végződik", "isCorrect": false}, {"id": "aeff51c1-3c06-4ea2-b979-00ab7c8c1238", "text": "Ha páratlan", "isCorrect": false}, {"id": "5958e9fa-2eec-469e-87a6-b80cf296954e", "text": "Ha a számjegyek összege 5", "isCorrect": false}], "timeLimit": 15}, {"id": "3d3f49b7-58aa-4eec-b811-d7c339a3cb86", "text": "Mikor osztható egy szám 10-zel?", "type": "multiple-choice", "options": [{"id": "844f6f19-5d44-4697-89a6-ed44e2bb7e0c", "text": "Ha az utolsó számjegye 0", "isCorrect": true}, {"id": "1ea32b18-b6b2-465b-bf28-082cf9ff0ca4", "text": "Ha az utolsó számjegye 5", "isCorrect": false}, {"id": "65677ef5-c7df-4fb0-85ca-0377599c3acd", "text": "Ha páros", "isCorrect": false}, {"id": "5a9130b9-34f2-4a4e-8ee7-72b4e962a35f", "text": "Ha 10 számjegyből áll", "isCorrect": false}], "timeLimit": 15}, {"id": "138c1f10-129b-422d-8ddc-e1d0f134508f", "text": "A 435 osztható 5-tel.", "type": "true-false", "options": [{"id": "9e257647-31f0-409c-b028-afa6ba2d4b0c", "text": "Igaz", "isCorrect": true}, {"id": "7768d0c4-5285-46d6-87ce-b47db475c67e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "554dcc8c-042d-4dc0-90a1-82978cb172b0", "text": "A 680 osztható 2-vel, 5-tel és 10-zel is.", "type": "true-false", "options": [{"id": "36aec063-e6bc-44d4-a235-61555ff0db44", "text": "Igaz", "isCorrect": true}, {"id": "dcdf08bb-ccdb-4f2e-b51b-74ab249b87f3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "883e4e10-dfdc-442d-aff7-70cccbda0912", "text": "Osztható-e a 789 2-vel?", "type": "true-false", "options": [{"id": "7ced5836-53cd-454e-adcc-dd2623463333", "text": "Igaz", "isCorrect": false}, {"id": "b56c82c9-e878-4a17-b615-1f399c20030b", "text": "Hamis (páratlanra végződik)", "isCorrect": true}], "timeLimit": 15}, {"id": "c739e91f-5057-488b-afa5-50a045eb118e", "text": "Melyik számjegy állhat a 45_ végén, hogy a szám osztható legyen 10-zel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9ed7d959-1867-46a8-bd0d-6accde2628dc', '21feff02-016d-46e2-bb9d-c27495133b1b', '18. óra: Oszthatóság 3-mal és 9-cel', 'A számjegyek összegén alapuló oszthatósági szabályok.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "6d5394c5-8071-4c56-acef-130e2344c66b", "text": "Mikor osztható egy szám 3-mal?", "type": "multiple-choice", "options": [{"id": "ac51c635-873f-4f00-89ed-bef1909a7713", "text": "Ha a számjegyeinek összege osztható 3-mal", "isCorrect": true}, {"id": "d621c5af-4704-4b74-b1b8-2a37028570f6", "text": "Ha 3-ra végződik", "isCorrect": false}, {"id": "0ab9f24c-f4a8-48c5-a04e-4c1d7e8a762e", "text": "Ha páratlan", "isCorrect": false}, {"id": "4e512caf-6369-4e6b-8593-c2e7a603f29f", "text": "Ha az utolsó számjegye 3, 6 vagy 9", "isCorrect": false}], "timeLimit": 15}, {"id": "95608565-00fb-4aab-8689-778f64107e5b", "text": "Mikor osztható egy szám 9-cel?", "type": "multiple-choice", "options": [{"id": "a149c7fc-020c-421e-b9a8-1ee22f20bb6b", "text": "Ha a számjegyeinek összege osztható 9-cel", "isCorrect": true}, {"id": "d7de0ed0-22a4-4b73-829b-249bcacf89a2", "text": "Ha 9-re végződik", "isCorrect": false}, {"id": "9eb75873-17a5-4bae-8669-6fa354ae3f94", "text": "Ha 3-ra végződik", "isCorrect": false}, {"id": "90e948d3-b716-4229-8ef3-2a1dcc541bce", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "b46e4be3-f0c9-4eac-9b8c-c5a7b9f6b10d", "text": "Mennyi a 243 számjegyeinek összege (2+4+3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "48f7f73e-4683-47ec-abe9-54a1b3b4511e", "text": "A 243 osztható 3-mal és 9-cel is.", "type": "true-false", "options": [{"id": "e32555ba-4f96-43a7-8b47-605c9590e3d0", "text": "Igaz", "isCorrect": true}, {"id": "494dc20c-0e6e-4d21-8d50-e4f8d0dac543", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "269972ff-202a-4efd-96c8-2b69548a10f9", "text": "Ha egy szám osztható 9-cel, akkor 3-mal is osztható.", "type": "true-false", "options": [{"id": "eb2e2454-2ee7-4f93-b4ad-0a92bf04c630", "text": "Igaz", "isCorrect": true}, {"id": "91e6e95c-2c57-4818-aae2-449e544e0ed6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e263e4ea-f072-4a92-a57e-9bfa8daef0a9", "text": "Osztható-e a 124 3-mal? (számjegyösszeg: 1+2+4=7)", "type": "true-false", "options": [{"id": "cdc2e2c1-4b4c-47bc-8707-8ece933f0506", "text": "Igaz", "isCorrect": false}, {"id": "a4748ae2-8551-44a2-b225-1ffb6c539fa6", "text": "Hamis", "isCorrect": true}], "timeLimit": 15}, {"id": "d20e4e77-4319-46f8-9c76-cb77a0f9dacd", "text": "Melyik számjegyet kell az X helyére írni a 51X számban, hogy osztható legyen 9-cel? (5+1+X=9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('fc457611-3ff8-4daf-883a-1bcbd2e4534d', '21feff02-016d-46e2-bb9d-c27495133b1b', '19. óra: Oszthatóság 4-gyel és 100-zal', 'Oszthatósági szabály az utolsó két számjegy alapján.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "ac37fa70-2a1e-4cbf-acdf-f9a158eda9f6", "text": "Mikor osztható egy szám 4-gyel?", "type": "multiple-choice", "options": [{"id": "368dcca4-882a-4703-92b5-87d48c72e6c3", "text": "Ha az utolsó két számjegyéből képzett kétjegyű szám osztható 4-gyel (vagy 00)", "isCorrect": true}, {"id": "b9f57888-3003-4668-9593-2c3f65561d47", "text": "Ha 4-re végződik", "isCorrect": false}, {"id": "19ae5716-2a31-42c8-ac78-6ba16134b433", "text": "Ha a számjegyek összege 4", "isCorrect": false}, {"id": "ab9131e7-5958-42e7-a296-bba1b9f3353d", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "353172f3-985b-4680-a97c-935c38188b69", "text": "Mikor osztható egy szám 100-zal?", "type": "multiple-choice", "options": [{"id": "c700f68e-465d-47c2-a7aa-620676429050", "text": "Ha az utolsó két számjegye 00", "isCorrect": true}, {"id": "0533e5d6-7e33-4670-b080-665fde0197b5", "text": "Ha 100-ra végződik", "isCorrect": false}, {"id": "78834952-12eb-4677-a4e9-2081f9c95164", "text": "Ha 0-ra végződik", "isCorrect": false}, {"id": "11214768-fdd8-41c0-83a1-1cdfae3191ff", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "de65116c-082e-4ed8-8aa7-bbd2524165fd", "text": "A 316 osztható 4-gyel (mert 16 osztható 4-gyel).", "type": "true-false", "options": [{"id": "e2302780-1e1d-4210-8ca1-ca567fdfb636", "text": "Igaz", "isCorrect": true}, {"id": "b537eee4-9f2f-4281-9900-e4fb2c8dc28e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c966d58a-73e9-4734-ad94-50decfa96be4", "text": "A 7500 osztható 100-zal és 4-gyel is.", "type": "true-false", "options": [{"id": "7a3e3a1f-edf6-415e-a244-d542b3293ec7", "text": "Igaz", "isCorrect": true}, {"id": "e38b4bae-eff0-4c1f-a6f5-f97eb6326a28", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1a113da7-6223-47a9-baac-f26277e1f0ed", "text": "Osztható-e a 522 4-gyel? (22 / 4 = 5 maradék 2)", "type": "true-false", "options": [{"id": "f4facf3a-3079-4870-ad36-6a6475c270d6", "text": "Igaz", "isCorrect": false}, {"id": "8c7ead8d-8de0-4523-ab51-bc694aa5a930", "text": "Hamis", "isCorrect": true}], "timeLimit": 15}, {"id": "e3b345c3-a4bb-4130-bc2a-b9582b79f9b9", "text": "Melyik legkisebb kétjegyű szám osztható 4-gyel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "c4121999-bf55-425a-83ab-41edd0eaec61", "text": "A 1000 osztható 4-gyel.", "type": "true-false", "options": [{"id": "e4311ebf-69c2-41e9-8750-a86771c808da", "text": "Igaz (00-ra végződik)", "isCorrect": true}, {"id": "1484a421-beee-4193-82ea-c0790fd76986", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());